-- SEC-100 Operations/SOC internal operational view.
-- Does not imply contracted 24x7 human monitoring or public dispatch.
CREATE OR REPLACE FUNCTION public.app_has_operations_access(p_organization_id uuid,p_neighborhood_id uuid,p_property_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public','auth' AS $$ SELECT public.app_is_platform_admin() OR EXISTS(SELECT 1 FROM public.memberships m JOIN public.app_users u ON u.id=m.user_id WHERE m.organization_id=p_organization_id AND m.status='active' AND u.status='active' AND u.auth_user_id=NULLIF(auth.user_id(),'')::uuid AND (m.role='admin_organization' OR (m.role='admin_neighborhood' AND p_neighborhood_id IS NOT NULL AND m.neighborhood_id=p_neighborhood_id) OR (m.role='monitoring' AND (m.neighborhood_id IS NULL OR m.neighborhood_id=p_neighborhood_id) AND (m.property_id IS NULL OR m.property_id=p_property_id)))) $$;
CREATE OR REPLACE FUNCTION public.get_operations_overview() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public','auth','pg_temp' AS $$ SELECT jsonb_build_object('devices_total',(SELECT count(*) FROM public.devices d WHERE public.app_has_operations_access(d.organization_id,d.neighborhood_id,d.property_id)),'devices_offline',(SELECT count(*) FROM public.devices d WHERE d.status='offline' AND public.app_has_operations_access(d.organization_id,d.neighborhood_id,d.property_id)),'devices_degraded',(SELECT count(*) FROM public.devices d WHERE d.status='degraded' AND public.app_has_operations_access(d.organization_id,d.neighborhood_id,d.property_id)),'events_unack_high_critical',(SELECT count(*) FROM public.security_events e WHERE e.acknowledged_at IS NULL AND e.severity IN ('high','critical') AND public.app_has_operations_access(e.organization_id,e.neighborhood_id,e.property_id)),'events_pending_validation',(SELECT count(*) FROM public.security_events e WHERE e.human_validation_status='pending' AND public.app_has_operations_access(e.organization_id,e.neighborhood_id,e.property_id)),'incidents_active',(SELECT count(*) FROM public.incidents i WHERE i.status IN ('open','investigating','monitoring') AND public.app_has_operations_access(i.organization_id,i.neighborhood_id,i.property_id)),'incidents_critical',(SELECT count(*) FROM public.incidents i WHERE i.status IN ('open','investigating','monitoring') AND i.severity='critical' AND public.app_has_operations_access(i.organization_id,i.neighborhood_id,i.property_id)),'sos_active',(SELECT count(*) FROM public.sos_requests s WHERE s.status IN ('open','acknowledged') AND public.app_has_operations_access(s.organization_id,s.neighborhood_id,s.property_id)),'community_maintenance_open',(SELECT count(*) FROM public.community_maintenance cm WHERE cm.status IN ('open','in_progress') AND public.app_has_operations_access(cm.organization_id,cm.neighborhood_id,NULL)),'human_monitoring_assumed',false,'public_dispatch_enabled',false) $$;
CREATE OR REPLACE FUNCTION public.get_operations_attention_feed(p_limit integer DEFAULT 100) RETURNS TABLE(item_type text,item_id uuid,severity text,status text,title text,scope text,occurred_at timestamptz,organization_id uuid,neighborhood_id uuid,property_id uuid) LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public','auth','pg_temp' AS $$ WITH queue AS (SELECT 'sos'::text s_type,s.id s_id,'critical'::text sev,s.status st,'SOS · '||left(s.occurrence,120) ttl,'private'::text sc,s.created_at ts,s.organization_id org,s.neighborhood_id nb,s.property_id prop FROM public.sos_requests s WHERE s.status IN ('open','acknowledged') AND public.app_has_operations_access(s.organization_id,s.neighborhood_id,s.property_id) UNION ALL SELECT 'incident',i.id,i.severity::text,i.status,i.title,CASE WHEN i.property_id IS NULL THEN 'community' ELSE 'private' END,i.opened_at,i.organization_id,i.neighborhood_id,i.property_id FROM public.incidents i WHERE i.status IN ('open','investigating','monitoring') AND public.app_has_operations_access(i.organization_id,i.neighborhood_id,i.property_id) UNION ALL SELECT 'event',e.id,e.severity::text,CASE WHEN e.acknowledged_at IS NULL THEN 'unacknowledged' ELSE 'acknowledged' END,e.event_type,CASE WHEN e.property_id IS NULL THEN 'community' ELSE 'private' END,e.occurred_at,e.organization_id,e.neighborhood_id,e.property_id FROM public.security_events e WHERE e.severity IN ('high','critical') AND e.acknowledged_at IS NULL AND public.app_has_operations_access(e.organization_id,e.neighborhood_id,e.property_id) UNION ALL SELECT 'device',d.id,CASE WHEN d.status='offline' THEN 'high' ELSE 'attention' END,d.status::text,d.name,CASE WHEN d.property_id IS NULL THEN 'community' ELSE 'private' END,COALESCE(d.last_status_changed_at,d.last_seen_at,d.created_at),d.organization_id,d.neighborhood_id,d.property_id FROM public.devices d WHERE d.status IN ('offline','degraded') AND public.app_has_operations_access(d.organization_id,d.neighborhood_id,d.property_id) UNION ALL SELECT 'maintenance',cm.id,cm.priority,cm.status,cm.title,'community',cm.created_at,cm.organization_id,cm.neighborhood_id,NULL::uuid FROM public.community_maintenance cm WHERE cm.status IN ('open','in_progress') AND cm.priority IN ('high','critical') AND public.app_has_operations_access(cm.organization_id,cm.neighborhood_id,NULL)) SELECT s_type,s_id,sev,st,ttl,sc,ts,org,nb,prop FROM queue ORDER BY CASE sev WHEN 'critical' THEN 0 WHEN 'high' THEN 1 ELSE 2 END,ts DESC LIMIT LEAST(GREATEST(p_limit,1),500) $$;
CREATE OR REPLACE FUNCTION public.get_operations_network_health() RETURNS TABLE(organization_id uuid,neighborhood_id uuid,neighborhood_name text,devices_total bigint,devices_online bigint,devices_offline bigint,devices_degraded bigint,last_seen_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public','auth','pg_temp' AS $$ SELECT d.organization_id,d.neighborhood_id,COALESCE(n.name,'Sem bairro')::text,count(*) AS devices_total,count(*) FILTER(WHERE d.status='online') AS devices_online,count(*) FILTER(WHERE d.status='offline') AS devices_offline,count(*) FILTER(WHERE d.status='degraded') AS devices_degraded,max(d.last_seen_at) AS last_seen_at FROM public.devices d LEFT JOIN public.neighborhoods n ON n.id=d.neighborhood_id WHERE public.app_has_operations_access(d.organization_id,d.neighborhood_id,d.property_id) GROUP BY d.organization_id,d.neighborhood_id,n.name ORDER BY count(*) FILTER(WHERE d.status='offline') DESC,count(*) DESC $$;
REVOKE ALL ON FUNCTION public.app_has_operations_access(uuid,uuid,uuid),public.get_operations_overview(),public.get_operations_attention_feed(integer),public.get_operations_network_health() FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.app_has_operations_access(uuid,uuid,uuid),public.get_operations_overview(),public.get_operations_attention_feed(integer),public.get_operations_network_health() TO authenticated;COMMENT ON FUNCTION public.get_operations_overview() IS 'Operational aggregation only. Does not imply contracted 24x7 human monitoring or public dispatch.';
